 * fullscreen fragment over the frame. Subclass this directly for anything else.
 * @example
 * ```ts
 * class MyRearViewPass extends Pass3D {
 *   public readonly stage = 'afterTransparent';
 *
 *   public build(graph: RenderGraph, ctx: PassContext): void {
