   * @default 0.1
   * @example
   * ```ts
   * camera.near = 0.5;
   * ```
   */
  near: number;
  /**
   * Distance to the far clipping plane, in world units; anything further isn't drawn
   * @default 1000
   * @example
   * ```ts
   * camera.far = 200;
   * ```
   */
